 const fn to_unknown (& self) -> LazyStateID { LazyStateID :: new_unchecked (self . as_usize_unchecked () | LazyStateID :: MASK_UNKNOWN ,) } # [inline] pub (crate) const fn to_dead (& self) -> LazyStateID { LazyStateID :: new_unchecked (self . as_usize_unchecked () | LazyStateID :: MASK_DEAD ,) } # [inline] pub (crate) const fn to_quit (& self) -> LazyStateID { LazyStateID :: new_unchecked (self . as_usize_unchecked () | LazyStateID :: MASK_QUIT ,) } # [doc = " Return this lazy state ID as a state ID that is tagged as a start"] # [doc = " state."] # [inline] pub (crate) const fn to_start (& self) -> LazyStateID { LazyStateID :: new_unchecked (self . as_usize_unchecked () | LazyStateID :: MASK_START ,) } # [doc = " Return this lazy state ID as a lazy state ID that is tagged as a match"] # [doc = " state."] # [inline] pub (crate) const fn to_match (& self) -> LazyStateID { LazyStateID :: new_unchecked (self . as_usize_unchecked () | LazyStateID :: MASK_MATCH ,) } # [doc = " Return true if and only if this lazy state ID is tagged."] # [doc = ""] # [doc = " When a lazy state ID is tagged, then one can conclude that it is one"] # [doc = " of a match, start, dead, quit or unknown state."] # [inline] pub const fn is_tagged (& self) -> bool { self . as_usize_unchecked () > LazyStateID :: MAX } # [doc = " Return true if and only if this represents a lazy state ID that is"] # [doc = " \"unknown.\" That is, the state has not yet been created. When a caller"] # [doc = " sees this state ID, it generally means that a state has to be computed"] # [doc = " in order to proceed."] # [inline] pub const fn is_unknown (& self) -> bool { self . as_usize_unchecked () & LazyStateID :: MASK_UNKNOWN > 0 } # [doc = " Return true if and only if this represents a dead state. A dead state"] # [doc = " is a state that can never transition to any other state except the"] # [doc = " dead state. When a dead state is seen, it generally indicates that a"] # [doc = " search should stop."] # [inline] pu